import {t,getLocale} from './locales.js';
import {cowCapacity,cowSupply} from './cow-state.js';
import {cowCareReason} from './cow-care.js';
export const COW_OBJECT_KEYS=Object.freeze({barn:'cowBarnShelter',feed:'cowFeeder',water:'cowWaterTrough',stand:'cowMilkingStand',can:'cowMilkCan',coop:'cowCoop',clean:'cowCleanStation'});
/** @param {number} n */
const number=n=>n.toLocaleString(getLocale(),{maximumFractionDigits:2});
/** @param {string} id @param {import('./engine.js').State} state */
export function validCowSelection(id,state){return !!state.cow?.visited&&(Object.hasOwn(COW_OBJECT_KEYS,id)||state.cow.cows.some(c=>c.id===id));}
/** @param {HTMLElement} list @param {string} key @param {string} value */
function fact(list,key,value){const group=document.createElement('div'),term=document.createElement('dt'),definition=document.createElement('dd');term.textContent=t(key);definition.textContent=value;group.append(term,definition);list.append(group);}
/** @param {import('./engine.js').State} state @param {boolean} visible */
export function renderCowHud(state,visible){const panel=/** @type {HTMLElement} */(document.querySelector('#cow-hud'));panel.hidden=!visible;if(!visible||!state.cow?.visited)return;const g=state.cow,cap=cowCapacity(g),list=/** @type {HTMLElement} */(document.querySelector('#cow-hud-status'));panel.setAttribute('aria-label',t('cowHud'));list.replaceChildren();fact(list,'cowCount',g.cows.length+' / '+cap.cows);fact(list,'cowFeedReady',number(cowSupply(g.feedTrough)/1000)+' / '+number(cap.feedG/1000)+' kg');fact(list,'cowWaterReady',number(cowSupply(g.waterTrough)/1000)+' / '+number(cap.waterMl/1000)+' L');fact(list,'cowComfort',number(g.cows.reduce((n,c)=>n+c.comfort,0)/g.cows.length/10)+'%');fact(list,'cowMilkReady',number(g.cows.reduce((n,c)=>n+c.milkReadyMl,0)/1000)+' L');fact(list,'cowMilkStored',number(g.lots.reduce((n,l)=>n+l.remainingVolumeMl,0)/1000)+' L');fact(list,'cowCollectedGrade',g.lots.length?[...new Set(g.lots.map(l=>l.gradeAtMilking))].join(' / '):t('cowNotCollected'));fact(list,'cowCoop',t('cowCoopReady'));}
/** @typedef {(type:import('./engine.js').CommandType,extra?:Partial<import('./engine.js').Command>)=>unknown} CowSend */
/** @param {import('./engine.js').State} state @param {string} selected @param {CowSend} send */
export function renderCowPanel(state,selected,send){const panel=/** @type {HTMLElement} */(document.querySelector('#cow-panel'));panel.hidden=!selected;const g=state.cow;if(!selected||!g?.barn)return;const active=panel.contains(document.activeElement)?/** @type {HTMLElement} */(document.activeElement)?.dataset.cowAction:undefined,cow=g.cows.find(c=>c.id===selected),heading=/** @type {HTMLElement} */(document.querySelector('#cow-heading')),cap=cowCapacity(g);heading.textContent=cow?t('cowName')+' '+(cow.id==='cow.starter.a'?'A':cow.id==='cow.starter.b'?'B':'C'):t(COW_OBJECT_KEYS[/** @type {keyof typeof COW_OBJECT_KEYS} */(selected)]);const copy=/** @type {HTMLElement} */(document.querySelector('#cow-selection-copy'));copy.textContent=cow?t(cow.lactationStatus==='lactating'?'cowLactating':'cowDry')+' · '+t('cowMilkReady')+': '+number(cow.milkReadyMl/1000)+' L':t('cowWelcomeDetail');const status=/** @type {HTMLElement} */(document.querySelector('#cow-status'));status.replaceChildren();
 if(cow){fact(status,'cowComfort',number(cow.comfort/10)+'%');fact(status,'cowMilkReady',number(cow.milkReadyMl/1000)+' / 10 L');fact(status,'cowMilkProduced',number(cow.producedMilkMl/1000)+' L');}
 else if(selected==='feed'){fact(status,'cowFeedReady',number(cowSupply(g.feedTrough)/1000)+' / '+number(cap.feedG/1000)+' kg');fact(status,'cowAidFeed',number((g.starterRation.feedG+g.recoveryRation.feedG)/1000)+' kg');fact(status,'cowPaidFeed',number(g.feedStoreG/1000)+' kg');}
 else if(selected==='water'){fact(status,'cowWaterReady',number(cowSupply(g.waterTrough)/1000)+' / '+number(cap.waterMl/1000)+' L');fact(status,'cowAidWater',number((g.starterRation.waterMl+g.recoveryRation.waterMl)/1000)+' L');fact(status,'cowSharedWater',number(state.water)+' L');}
 else if(selected==='stand')fact(status,'cowHygiene',g.barn.standCleanliness+'%');else if(selected==='can')fact(status,'cowHygiene',g.barn.canCleanliness+'%');else fact(status,'cowHygiene',g.barn.cleanliness+'%');
 const actions=/** @type {HTMLElement} */(document.querySelector('#cow-actions'));actions.replaceChildren();const buttons=/** @type {Array<[import('./engine.js').CommandType,string]>} */([]);if(cow)buttons.push(['inspectCow','cowInspect']);if(selected==='feed')buttons.push(['feedCows','cowFillFeed']);if(selected==='water')buttons.push(['waterCows','cowFillWater']);if(selected==='barn'||selected==='clean')buttons.push(['cleanCowBarn','cowCleanBarn']);if(selected==='stand'||selected==='clean')buttons.push(['cleanCowStand','cowCleanStand']);if(selected==='can'||selected==='clean')buttons.push(['cleanCowCan','cowCleanCan']);for(const [type,key]of buttons){const box=document.createElement('div'),button=document.createElement('button'),reason=cowCareReason(state,type,selected);box.className='cow-action';button.type='button';button.className='action-button';button.dataset.cowAction=type;button.textContent=t(key);button.disabled=!!reason;button.title=reason?t(reason):'';button.addEventListener('click',()=>send(type,type==='inspectCow'?{cowId:selected}:{}));box.append(button);if(reason){const explanation=document.createElement('p');explanation.className='cow-reason';explanation.textContent=t(reason);box.append(explanation);}actions.append(box);}if(selected==='coop'||selected==='feed'){const button=document.createElement('button');button.type='button';button.className='action-button';button.textContent=t('marketTitle');button.addEventListener('click',()=>document.dispatchEvent(new Event('marketopen')));actions.append(button);}if(active){const next=/** @type {HTMLButtonElement|null} */(panel.querySelector('[data-cow-action="'+active+'"]'));if(next&&!next.disabled)next.focus({preventScroll:true});else heading.focus({preventScroll:true});}}
